/* ==========================================================================
 *  Exports
 * ========================================================================== */

export default {
  REALM_TIER_TEMPLATES,
  CHARACTER_STATUS_TEMPLATES,
  FACTION_LEVEL_TEMPLATES,
}

/** 获取境界大阶模板列表（下拉） */
export function getRealmTierTemplateList() {
  return REALM_TIER_TEMPLATES.map((t) => ({
    key: t.key, name: t.name, icon: t.icon, tags: t.tags, desc: t.desc, count: t.tiers.length,
  }))
}

/** 获取角色状态模板列表 */
export function getCharacterStatusTemplateList() {
  return CHARACTER_STATUS_TEMPLATES.map((t) => ({
    key: t.key, name: t.name, icon: t.icon, tags: t.tags, count: t.statuses.length,
  }))
}

/** 获取族群等级模板列表 */
export function getFactionLevelTemplateList() {
  return FACTION_LEVEL_TEMPLATES.map((t) => ({
    key: t.key, name: t.name, icon: t.icon, tags: t.tags, count: t.levels.length,
  }))
}

/** 根据 key 获取境界大阶完整模板 */
export function getRealmTierTemplate(key) {
  return REALM_TIER_TEMPLATES.find((x) => x.key === key)?.tiers || []
}

/** 根据 key 获取角色状态完整模板 */
export function getCharacterStatusTemplate(key) {
  return CHARACTER_STATUS_TEMPLATES.find((x) => x.key === key)?.statuses || []
}

/** 根据 key 获取族群等级完整模板 */
export function getFactionLevelTemplate(key) {
  return FACTION_LEVEL_TEMPLATES.find((x) => x.key === key)?.levels || []
}
